using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public sealed class DoorPlayModeChecks : MonoBehaviour
{
 [Serializable]public class Result{public bool finished,passed;public string error;public List<string> checks=new List<string>();public List<string> diagnostics=new List<string>();}public Result report=new Result();
 DoorMonsterEncounter ai;BedroomPhaseController p;Keyboard keyboard;InputSettings original,test;DoorEncounterConfig[] originals;
 void Check(bool value,string label){report.checks.Add((value?"PASS: ":"FAIL: ")+label);if(!value)throw new Exception(label);}
 void Key(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}
 IEnumerator Wait(Func<bool> predicate,float seconds=12){float end=Time.realtimeSinceStartup+seconds;while(!predicate()&&Time.realtimeSinceStartup<end)yield return null;if(!predicate())throw new Exception("Timed out at "+ai.State);}
 IEnumerator Start(){ai=FindAnyObjectByType<DoorMonsterEncounter>();p=ai.phases;SchedulingTestOverride.Configure(ai.director,100);original=InputSystem.settings;test=Instantiate(original);test.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;test.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=test;keyboard=InputSystem.AddDevice<Keyboard>();originals=ai.nightConfigs;ai.nightConfigs=originals.Select(Instantiate).ToArray();foreach(var c in ai.nightConfigs){c.initialDelay=100;c.footstepsDuration=.25f;c.approachSilence=.1f;c.gentleDuration=.25f;c.aggressiveDuration=.3f;c.silenceAfterBanging=.2f;c.handleDuration=.15f;c.openingDuration=.4f;c.retreatDuration=.5f;c.cooldown=new Vector2(.4f,.4f);c.attackDuration=.2f;}ai.director.quietInterval=.1f;var under=FindAnyObjectByType<UnderBedMonsterAI>();under.SetEncountersEnabled(false);var stack=new System.Collections.Generic.Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next=null;bool more=false;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){report.error=ex.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested){stack.Push(nested);continue;}yield return next;}Key();InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(test);foreach(var c in ai.nightConfigs)Destroy(c);ai.nightConfigs=originals;report.finished=true;report.passed=report.error==null;System.IO.File.WriteAllText("Temp/BedroomPrototype/DoorPlayModeChecks.json",JsonUtility.ToJson(report,true));Debug.Log("Door checks "+report.passed+" "+report.error);}
 void Reply(){p.ui.ActiveButtonRoot.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.gameObject.activeSelf&&b!=p.ui.buttonTemplate).onClick.Invoke();}
 IEnumerator Run(){yield return null;Check(!ai.ForceStartEncounter(),"door cannot start in morning");Key(UnityEngine.InputSystem.Key.R);yield return null;yield return null;Check(!ai.breath.IsHolding,"R inactive in morning");Key();p.SitAtDesk();yield return Wait(()=>p.State==BedroomPhase.MorningDesk&&!p.IsTransitioning);p.ui.OpenLaptop();Reply();Reply();p.ui.CloseModal();p.ui.OpenTruth();for(int i=0;i<p.tasks.Definition.conversation.Length;i++)Reply();p.ui.CloseModal();Check(p.tasks.BedUnlocked,"existing morning laptop and Truth interactions unlock bed");p.StandUp();yield return Wait(()=>p.State==BedroomPhase.MorningExploration&&!p.IsTransitioning);p.ceilingSwitch.SetLight(false);p.GoToBed();yield return Wait(()=>ai.NightActive);yield return null;
 Check(!p.movement.enabled&&!p.capsule.enabled,"player stationary in bed");var hud=p.ui.GetComponent<DoorEncounterHUD>();Check(!hud.debugPanel.activeSelf,"door debug starts hidden");Key(UnityEngine.InputSystem.Key.F4);yield return null;yield return null;Check(hud.debugPanel.activeSelf&&hud.debugText.text.Contains("Breath"),"F4 displays state, listening timer and breath meter");Key();yield return null;Key(UnityEngine.InputSystem.Key.F4);yield return null;yield return null;Key();yield return null;Check(!hud.debugPanel.activeSelf&&!p.IsObservationLocked,"closing F4 releases its own camera lock");Check(ai.ForceStartEncounter(),"force starts at night");Check(ai.State==DoorMonsterState.Approaching,"footsteps precede knocks");yield return Wait(()=>ai.State==DoorMonsterState.GentleKnocking);Check(Quaternion.Angle(ai.hinge.localRotation,Quaternion.identity)<.1f,"door closed for gentle knocks");yield return Wait(()=>ai.State==DoorMonsterState.AggressiveKnocking);Check(ai.aggressiveSource!=ai.gentleSource,"separate progressive knock channels");yield return Wait(()=>ai.State==DoorMonsterState.DoorOpening);yield return new WaitForSeconds(.25f);Check(Quaternion.Angle(ai.handle.localRotation,Quaternion.identity)>5,"handle physically turns");yield return Wait(()=>ai.State==DoorMonsterState.Listening);Check(Quaternion.Angle(ai.hinge.localRotation,Quaternion.identity)>80,"door physically swings around hinge");Check(ai.visual.gameObject.activeSelf&&Vector3.Distance(ai.visual.position,ai.doorwayAnchor.position)<.05f,"humanoid appears in doorway");Check(!p.IsObservationLocked,"listening allows camera movement");Key(UnityEngine.InputSystem.Key.R);yield return new WaitForSeconds(.2f);Check(ai.breath.IsHolding&&ai.breath.Capacity<1&&!ai.breath.breathingSource.isPlaying,"R consumes capacity and suppresses breath");
 yield return new WaitForEndOfFrame();Check(Vector3.Dot(ai.head.forward,(p.view.transform.position-ai.head.position).normalized)>.9f,"listening head faces protagonist after Animator update");var pic=ScreenCapture.CaptureScreenshotAsTexture();System.IO.File.WriteAllBytes("Temp/BedroomPrototype/DoorListening.png",pic.EncodeToPNG());Destroy(pic);
 yield return Wait(()=>ai.State==DoorMonsterState.Retreat);Check(ai.SuccessfulDefenses==1,"survives full three-second listening check");Key();yield return Wait(()=>ai.State==DoorMonsterState.Dormant);Check(!ai.visual.gameObject.activeSelf&&Quaternion.Angle(ai.hinge.localRotation,Quaternion.identity)<.1f,"retreat hides model and closes door");yield return Wait(()=>ai.State==DoorMonsterState.Approaching);Check(true,"cooldown schedules new encounter");yield return Wait(()=>ai.State==DoorMonsterState.Listening);Key(UnityEngine.InputSystem.Key.R);yield return new WaitForSeconds(1);Key();yield return Wait(()=>p.State==BedroomPhase.NightLost);Check(ai.FailedDefenses==1,"release during listening uses existing loss");Check(!ai.visual.gameObject.activeSelf&&!ai.breath.InputActive,"loss cleans enemy and breath input");p.RetryNight();yield return null;yield return null;ai.ResetEncounter();yield return new WaitForSeconds(.2f);Check(ai.ForceStartEncounter(),"retry supports encounter reset");Key(UnityEngine.InputSystem.Key.R);yield return new WaitForSeconds(.8f);Check(ai.breath.Capacity<.9f,"early hold consumes finite capacity before listening");ai.breath.maximumHoldSeconds=1.6f;yield return Wait(()=>p.State==BedroomPhase.NightLost);Check(ai.breath.GaspCount>0,"exhaustion triggers involuntary gasp and attack");Key();ai.breath.maximumHoldSeconds=6;p.RetryNight();yield return null;yield return null;ai.ResetEncounter();yield return new WaitForSeconds(.2f);Check(ai.ForceStartEncounter(),"starts after second retry");Check(!ai.director.TryStartEncounter(FindAnyObjectByType<UnderBedMonsterAI>()),"director blocks simultaneous under-bed encounter");p.night.nightDurationSeconds=.2f;p.night.BeginNight();yield return Wait(()=>p.State==BedroomPhase.NightWon);Check(ai.State==DoorMonsterState.Dormant&&!ai.visual.gameObject.activeSelf,"victory cancels encounter and closes door");Check(FindObjectsByType<Camera>().Count(x=>x.enabled)==1&&FindObjectsByType<AudioListener>().Count(x=>x.enabled)==1,"one gameplay camera and listener");}
 void Update(){if(!ai||ai.State!=DoorMonsterState.Listening)return;var b=ai.breath;string entry="frame="+Time.frameCount+" listen="+ai.StateElapsed.ToString("F2")+" holding="+b.IsHolding+" quiet="+b.IsQuiet+" cap="+b.Capacity.ToString("F2")+" require="+b.RequiresRelease+" allowed="+p.CanUseNightDefenses+" modal="+p.ui.ModalOpen+" guard="+p.ui.GameplayInputSuppressed+" keyboard="+(Keyboard.current!=null?Keyboard.current.deviceId:-1)+" physicalR="+(Keyboard.current!=null&&Keyboard.current.rKey.isPressed)+" actionR="+b.holdAction.IsPressed();report.diagnostics.Add(entry);if(report.diagnostics.Count>45)report.diagnostics.RemoveAt(0);} void OnDestroy(){if(original)InputSystem.settings=original;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(test)Destroy(test);}
}
